"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["11153"],{77037(e){e.exports=JSON.parse('{"id":"FIN-1304","slug":"repo-rate","term":"Repo Rate","also_known_as":[],"difficulty":"Advanced","definition":"The repo rate is the interest rate charged on a repurchase agreement, the short-term borrowing in which one party sells securities and agrees to buy them back at a slightly higher price. In some countries, it is also the name of the central bank\'s main policy rate.","explanation":["In a repurchase agreement, the difference between the sale price and the repurchase price represents the interest paid by the borrower. Expressed as an annual percentage, this is the repo rate.","For example, a bank that sells bonds for 10,000,000 and agrees to buy them back the next day for 10,001,000 is effectively paying 1,000 in interest for one night, equal to an annual repo rate of about 3.6% on a 365-day basis.","Market repo rates reflect the supply and demand for short-term secured funding and the quality of the collateral. They are watched closely as a sign of conditions in funding markets. In the United States, SOFR is based on repo transactions.","In several countries, including India and South Africa, the repo rate is the central bank\'s key policy rate, the rate at which it lends to commercial banks against collateral. Changes in this rate influence borrowing costs across the economy, much like the federal funds rate in the United States."],"note":"","total":1500,"prev":{"slug":"replacement-cost","term":"Replacement Cost"},"next":{"slug":"reporting-period","term":"Reporting Period"}}')}}]);